package ua.aia2.guard;
import java.util.*;
import net.minecraft.server.MinecraftServer;
/** Explicit receiver model. No production recorder or persistence implementation is replaced in game. */
public final class ProductionMilestoneBridge {
    public static final List<String> reads = new ArrayList<>();
    public static final Map<MinecraftServer,Map<String,Set<String>>> receipts = new IdentityHashMap<>();
    public static IllegalStateException failure;
    public static boolean configured = true;
    public static int writes;
    public static void grant(MinecraftServer server, String team, String proof) {
        receipts.computeIfAbsent(server, ignored -> new HashMap<>())
                .computeIfAbsent(team, ignored -> new HashSet<>()).add(proof);
    }
    public static boolean hasProof(MinecraftServer server, String team, String proof) {
        reads.add(team + ":" + proof);
        if (failure != null) throw failure;
        return receipts.getOrDefault(server, Map.of()).getOrDefault(team, Set.of()).contains(proof);
    }
}
